window.LQTACAudioLive=(()=>{
class Graph {
 constructor(media){this.media=media;this.context=new AudioContext({latencyHint:'interactive'});this.source=this.context.createMediaElementSource(media);this.analyser=this.context.createAnalyser();this.analyser.fftSize=1024;this.output=this.context.createGain();this.output.gain.value=1;this.worklet=null;this.closed=false;this.current={};this.ready=this.setup();}
 async setup(){const c=this.context;this.eq=[120,1000,8000].map(hz=>{const n=c.createBiquadFilter();n.type='peaking';n.frequency.value=hz;n.Q.value=1;return n;});this.comp=c.createDynamicsCompressor();this.comp.attack.value=.01;this.comp.release.value=.15;this.comp.knee.value=0;this.comp.ratio.value=1;
 let node=this.source;for(const n of [...this.eq,this.comp]){node.connect(n);node=n;}
 this.echo=c.createDelay(1.1);this.echoGain=c.createGain();this.echoGain.gain.value=0;node.connect(this.echo);this.echo.connect(this.echoGain);const echoSum=c.createGain();node.connect(echoSum);this.echoGain.connect(echoSum);
 this.reverbGain=c.createGain();this.reverbGain.gain.value=0;const taps=[29,43,71,113,173,251],weights=[.55,.45,.35,.25,.18,.1];this.taps=taps.map((ms,i)=>{const d=c.createDelay(.3),g=c.createGain();d.delayTime.value=ms/1000;g.gain.value=weights[i];echoSum.connect(d);d.connect(g);g.connect(this.reverbGain);return [d,g];});const sum=c.createGain();echoSum.connect(sum);this.reverbGain.connect(sum);
 try{await c.audioWorklet.addModule(new URL('assets/audio-preview-worklet.js',location.href).href);if(this.closed)return;this.worklet=new AudioWorkletNode(c,'lqtac-audition',{outputChannelCount:[2]});sum.connect(this.worklet);this.worklet.connect(this.analyser);}catch(e){if(this.closed)return;sum.connect(this.analyser);this.warning='Ruido/normalización/limitador no disponibles en preescucha: '+e.message;}
 this.analyser.connect(this.output);this.output.connect(c.destination);this.update(this.current.fx||{},this.current.bypass);}
 update(fx,bypass=false){this.current={fx,bypass};if(!this.eq)return;const c=this.context,t=c.currentTime,f=bypass?{}:fx;for(let i=0;i<3;i++)this.eq[i].gain.setTargetAtTime(f[['bass','mid','treble'][i]]||0,t,.015);this.comp.threshold.setTargetAtTime(f.compressor?f.thresholdDb:-24,t,.015);this.comp.ratio.setTargetAtTime(f.compressor?f.ratio:1,t,.015);this.echo.delayTime.setTargetAtTime((f.echoMs||250)/1000,t,.025);this.echoGain.gain.setTargetAtTime(f.echo?f.echoMix:0,t,.015);this.reverbGain.gain.setTargetAtTime(f.reverb?f.reverbMix:0,t,.015);if(this.worklet){const values={denoise:f.denoise?1:0,noiseDb:f.denoiseDb||0,normalize:f.normalize?1:0,targetLufs:f.targetLufs??-16,limiter:f.limiter?1:0,ceiling:f.limiterCeiling??.95};for(const [k,v]of Object.entries(values))this.worklet.parameters.get(k).setValueAtTime(v,t);}}
 async resume(){await this.ready;await this.context.resume();}
 peaks(){const a=new Float32Array(1024);this.analyser.getFloatTimeDomainData(a);return Array.from({length:180},(_,i)=>Math.max(...a.slice(Math.floor(i*a.length/180),Math.floor((i+1)*a.length/180)).map(Math.abs)));}
 close(){this.closed=true;this.source.disconnect();this.output.disconnect();void this.context.close();}
}
return {Graph};})();
